CREATE TYPE CATEGORY_TYPE AS ENUM (
    'PARFUM',
    'COSMETICS',
    'HOME_FRAGRANCE'
    );

CREATE TYPE ORDER_STATUS AS ENUM (
    'PENDING',
    'COMPLETED',
    'CANCELLED'
    );

CREATE TYPE TARGET_AUDIENCE AS ENUM (
    'MEN',
    'WOMEN',
    'UNISEX'
    );

CREATE TYPE TRANSACTION_TYPE AS ENUM (
    'ONLINE_ORDER',
    'IN_STORE_SALE'
    );

CREATE TYPE USER_ROLE AS ENUM (
    'CLIENT',
    'CASHIER',
    'MANAGER'
    );

CREATE TABLE IF NOT EXISTS "product" (
                                         "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                         "name" VARCHAR(255) NOT NULL,
                                         "brand" VARCHAR(255) NOT NULL,
                                         "category_type" CATEGORY_TYPE NOT NULL,
                                         "target_audience" TARGET_AUDIENCE,
                                         "description" TEXT,
                                         "volume_ml" INTEGER NOT NULL,
                                         "price" NUMERIC(10,2) NOT NULL,
                                         "release_year" INTEGER NOT NULL,
                                         "current_stock" INTEGER NOT NULL DEFAULT 0,
                                         "is_available" BOOLEAN NOT NULL DEFAULT TRUE,
                                         PRIMARY KEY ("id"),
                                         CONSTRAINT chk_product_name CHECK (BTRIM("name") <> ''),
                                         CONSTRAINT chk_product_brand CHECK (BTRIM("brand") <> ''),
                                         CONSTRAINT chk_product_volume CHECK ("volume_ml" > 0),
                                         CONSTRAINT chk_product_price CHECK ("price" >= 0),
                                         CONSTRAINT chk_product_release_year CHECK ("release_year" > 0),
                                         CONSTRAINT chk_product_stock CHECK ("current_stock" >= 0)
);

CREATE TABLE IF NOT EXISTS "price_history" (
                                               "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                               "product_id" BIGINT NOT NULL,
                                               "old_price" NUMERIC(10,2) NOT NULL,
                                               "new_price" NUMERIC(10,2) NOT NULL,
                                               "changed_at" TIMESTAMPTZ NOT NULL,
                                               PRIMARY KEY ("id"),
                                               CONSTRAINT chk_price_history_old CHECK ("old_price" >= 0),
                                               CONSTRAINT chk_price_history_new CHECK ("new_price" >= 0)
);

CREATE TABLE IF NOT EXISTS "stock_supply" (
                                              "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                              "product_id" BIGINT NOT NULL,
                                              "supplier_name" VARCHAR(255) NOT NULL,
                                              "quantity_added" INTEGER NOT NULL,
                                              "supply_date" DATE NOT NULL,
                                              "purchase_price" NUMERIC(10,2) NOT NULL,
                                              PRIMARY KEY ("id"),
                                              CONSTRAINT chk_supply_supplier CHECK (BTRIM("supplier_name") <> ''),
                                              CONSTRAINT chk_supply_quantity CHECK ("quantity_added" > 0),
                                              CONSTRAINT chk_supply_purchase_price CHECK ("purchase_price" >= 0)
);

CREATE TABLE IF NOT EXISTS "user_account" (
                                              "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                              "email" VARCHAR(255) NOT NULL UNIQUE,
                                              "password_hash" VARCHAR(255) NOT NULL,
                                              "first_name" VARCHAR(100) NOT NULL,
                                              "last_name" VARCHAR(100) NOT NULL,
                                              "phone" VARCHAR(25),
                                              "role" USER_ROLE NOT NULL,
                                              "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
                                              PRIMARY KEY ("id"),
                                              CONSTRAINT chk_user_email CHECK (BTRIM("email") <> ''),
                                              CONSTRAINT chk_user_password_hash CHECK (BTRIM("password_hash") <> ''),
                                              CONSTRAINT chk_user_first_name CHECK (BTRIM("first_name") <> ''),
                                              CONSTRAINT chk_user_last_name CHECK (BTRIM("last_name") <> ''),
                                              CONSTRAINT chk_user_phone CHECK ("phone" IS NULL OR BTRIM("phone") <> '')
);

CREATE TABLE IF NOT EXISTS "sale_transaction" (
                                                  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                                  "customer_id" BIGINT,
                                                  "employee_id" BIGINT,
                                                  "transaction_type" TRANSACTION_TYPE NOT NULL,
                                                  "delivery_address_id" BIGINT,
                                                  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
                                                  "status" ORDER_STATUS NOT NULL,
                                                  "total_price" NUMERIC(10,2) NOT NULL,
                                                  PRIMARY KEY ("id"),
                                                  CONSTRAINT chk_transaction_total CHECK ("total_price" >= 0),
                                                  CONSTRAINT chk_online_order_customer CHECK (
                                                      "transaction_type" <> 'ONLINE_ORDER' OR "customer_id" IS NOT NULL
                                                      ),
                                                  CONSTRAINT chk_store_sale_employee CHECK (
                                                      "transaction_type" <> 'IN_STORE_SALE' OR "employee_id" IS NOT NULL
                                                      )
);

CREATE TABLE IF NOT EXISTS "delivery_address" (
                                                  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                                  "user_id" BIGINT,
                                                  "street" VARCHAR(255) NOT NULL,
                                                  "city" VARCHAR(100) NOT NULL,
                                                  "postal_code" VARCHAR(20) NOT NULL,
                                                  "country" VARCHAR(10) NOT NULL,
                                                  PRIMARY KEY ("id"),
                                                  CONSTRAINT chk_address_street CHECK (BTRIM("street") <> ''),
                                                  CONSTRAINT chk_address_city CHECK (BTRIM("city") <> ''),
                                                  CONSTRAINT chk_address_postal_code CHECK (BTRIM("postal_code") <> ''),
                                                  CONSTRAINT chk_address_country CHECK (BTRIM("country") <> '')
);

CREATE TABLE IF NOT EXISTS "transaction_item" (
                                                  "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                                  "product_id" BIGINT NOT NULL,
                                                  "transaction_id" BIGINT NOT NULL,
                                                  "quantity" INTEGER NOT NULL,
                                                  "unit_price" NUMERIC(10,2) NOT NULL,
                                                  PRIMARY KEY ("id"),
                                                  CONSTRAINT chk_transaction_item_quantity CHECK ("quantity" > 0),
                                                  CONSTRAINT chk_transaction_item_unit_price CHECK ("unit_price" >= 0),
                                                  CONSTRAINT uq_transaction_product UNIQUE ("transaction_id", "product_id")
);

CREATE TABLE IF NOT EXISTS "fragrance_note" (
                                                "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                                "name" VARCHAR(255) NOT NULL UNIQUE,
                                                PRIMARY KEY ("id"),
                                                CONSTRAINT chk_fragrance_note_name CHECK (BTRIM("name") <> '')
);

CREATE TABLE IF NOT EXISTS "product_note" (
                                              "product_id" BIGINT NOT NULL,
                                              "note_id" BIGINT NOT NULL,
                                              PRIMARY KEY ("product_id", "note_id")
);

CREATE TABLE IF NOT EXISTS "product_image" (
                                               "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                               "product_id" BIGINT NOT NULL UNIQUE,
                                               "image_path" VARCHAR(500) NOT NULL,
                                               PRIMARY KEY ("id"),
                                               CONSTRAINT chk_product_image_path CHECK (BTRIM("image_path") <> '')
);

CREATE TABLE IF NOT EXISTS "cart" (
                                      "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                      "user_id" BIGINT NOT NULL UNIQUE,
                                      PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cart_item" (
                                           "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
                                           "cart_id" BIGINT NOT NULL,
                                           "product_id" BIGINT NOT NULL,
                                           "quantity" INTEGER NOT NULL,
                                           PRIMARY KEY ("id"),
                                           CONSTRAINT uq_cart_product UNIQUE ("cart_id", "product_id"),
                                           CONSTRAINT chk_cart_item_quantity CHECK ("quantity" > 0)
);

ALTER TABLE "price_history"
    ADD CONSTRAINT fk_price_history_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "stock_supply"
    ADD CONSTRAINT fk_stock_supply_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "sale_transaction"
    ADD CONSTRAINT fk_transaction_customer FOREIGN KEY ("customer_id")
        REFERENCES "user_account"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "sale_transaction"
    ADD CONSTRAINT fk_transaction_employee FOREIGN KEY ("employee_id")
        REFERENCES "user_account"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "delivery_address"
    ADD CONSTRAINT fk_address_user FOREIGN KEY ("user_id")
        REFERENCES "user_account"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "sale_transaction"
    ADD CONSTRAINT fk_transaction_address FOREIGN KEY ("delivery_address_id")
        REFERENCES "delivery_address"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "transaction_item"
    ADD CONSTRAINT fk_transaction_item_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "transaction_item"
    ADD CONSTRAINT fk_transaction_item_transaction FOREIGN KEY ("transaction_id")
        REFERENCES "sale_transaction"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "product_note"
    ADD CONSTRAINT fk_product_note_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "product_note"
    ADD CONSTRAINT fk_product_note_note FOREIGN KEY ("note_id")
        REFERENCES "fragrance_note"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "product_image"
    ADD CONSTRAINT fk_product_image_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "cart"
    ADD CONSTRAINT fk_cart_user FOREIGN KEY ("user_id")
        REFERENCES "user_account"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;

ALTER TABLE "cart_item"
    ADD CONSTRAINT fk_cart_item_cart FOREIGN KEY ("cart_id")
        REFERENCES "cart"("id") ON UPDATE NO ACTION ON DELETE CASCADE;

ALTER TABLE "cart_item"
    ADD CONSTRAINT fk_cart_item_product FOREIGN KEY ("product_id")
        REFERENCES "product"("id") ON UPDATE NO ACTION ON DELETE NO ACTION;